<?php
declare(strict_types=1); use DecisionRules\RuleSetRepository;
require __DIR__.'/_auth.php';$auth->requireRole('RULE_APPROVER');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$user=$auth->requireLogin();$repo=new RuleSetRepository($pdo);try{if(($_POST['action']??'')==='approve'){$repo->approve((int)$id,(int)$user['id'],$user['username']);$_SESSION['flash']='Rule Set approved and activated.';}elseif(($_POST['action']??'')==='reject'){$repo->reject((int)$id,(int)$user['id'],$user['username'],(string)($_POST['rejection_reason']??''));$_SESSION['flash']='Rule Set rejected.';}else throw new DomainException('Invalid action.');redirect('rule_sets.php');}catch(DomainException $e){http_response_code(str_contains($e->getMessage(),'contributed')?403:409);exit(e($e->getMessage()));}
